/* Direct, in-memory validation of our own parser. No encoding, transport,
 * controller, firmware, profile, or external target is used by this program. */
#include "bth_sco_setup.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static unsigned checks,cases;static uint32_t model_start=100;
#define CHECK(x) do{++checks;if(!(x)){fprintf(stderr,"FAIL line%d %s\n",__LINE__,#x);exit(2);}}while(0)
typedef struct {bth_sco_setup_t state;bth_sco_setup_command_t current;uint32_t now;} Model;
static bth_sco_setup_config_t configuration(bool optional_fallback){bth_sco_setup_config_t c;memset(&c,0,sizeof c);c.manufacturer=15;c.tx_bytes=64;c.tx_packets=1;c.allow_rx_pacing=optional_fallback;return c;}
static void initialize(Model* m,bool optional_fallback){memset(m,0,sizeof *m);m->now=model_start;const bth_sco_setup_config_t c=configuration(optional_fallback);CHECK(bth_sco_setup_init(&m->state,&c));}
static void intent(Model* m,uint16_t expected){CHECK(bth_sco_setup_next(&m->state,m->now,&m->current)==BTH_OK);CHECK(m->current.opcode==expected);/* Pure model bookkeeping, never a dispatch. */CHECK(bth_sco_setup_queued(&m->state,m->current.ticket,++m->now)==BTH_OK);}
static bth_status_t complete(Model* m,const uint8_t* result,size_t bytes){uint8_t parameters[68]={1,(uint8_t)m->current.opcode,(uint8_t)(m->current.opcode>>8)};CHECK(bytes<=65);if(bytes)memcpy(parameters+3,result,bytes);bth_h4_frame_t event;memset(&event,0,sizeof event);event.type=BTH_H4_EVENT;event.event.code=0x0e;event.event.params.data=parameters;event.event.params.len=bytes+3;return bth_sco_setup_on_event(&m->state,&event,++m->now);}
static bth_status_t command_status(Model* m,uint8_t status,size_t size,bool matching){uint8_t parameters[5]={status,1,(uint8_t)m->current.opcode,(uint8_t)(m->current.opcode>>8),0};CHECK(size<=5);if(!matching)parameters[2]^=1;bth_h4_frame_t event;memset(&event,0,sizeof event);event.type=BTH_H4_EVENT;event.event.code=0x0f;event.event.params.data=parameters;event.event.params.len=size;return bth_sco_setup_on_event(&m->state,&event,++m->now);}
static void model_flow_read(Model* m,bool fallback,bool advertised){initialize(m,fallback);uint8_t capabilities[65]={0};capabilities[11]=advertised?0xfc:0xec;intent(m,0x1002);CHECK(complete(m,capabilities,sizeof capabilities)==BTH_OK);CHECK(m->state.flow_write_supported==advertised);/* Existing route-read state is modelled only; no vendor procedure executes. */const uint8_t route[6]={0,1,2,3,0,1};intent(m,0xfc1d);CHECK(complete(m,route,sizeof route)==BTH_OK);intent(m,0x0c2e);}
static void model_advertised_write(Model* m,bool fallback){model_flow_read(m,fallback,true);const uint8_t off[2]={0,0};CHECK(complete(m,off,sizeof off)==BTH_OK);intent(m,0x0c2f);CHECK(m->current.length==1&&m->current.parameters[0]==1);}
static void model_verify(Model* m,bool fallback){model_advertised_write(m,fallback);const uint8_t accepted[1]={0};CHECK(complete(m,accepted,sizeof accepted)==BTH_OK);intent(m,0x0c2e);}
static void no_followup(Model* m){bth_sco_setup_command_t next;memset(&next,0xa5,sizeof next);CHECK(bth_sco_setup_next(&m->state,m->now,&next)==BTH_MORE&&next.opcode==0&&next.length==0);CHECK(bth_sco_setup_queued(&m->state,m->current.ticket,m->now)==BTH_IGNORED);}
static void invalid_result(Model* m,bool needs_reset){CHECK(m->state.done&&!m->state.pending&&!m->state.available&&!m->state.controller_flow&&!m->state.rx_paced);CHECK(m->state.reason==BTH_SCO_SETUP_MALFORMED&&m->state.requires_reset==needs_reset);no_followup(m);}
static void malformed_write_results(void){const size_t lengths[]={0,2,3,64};for(unsigned optional=0;optional<2;++optional)for(unsigned status=0;status<256;++status)for(unsigned l=0;l<sizeof lengths/sizeof lengths[0];++l){Model m;model_advertised_write(&m,optional!=0);uint8_t values[65]={0};values[0]=(uint8_t)status;CHECK(complete(&m,values,lengths[l])==BTH_OK);invalid_result(&m,true);++cases;}}
static void valid_write_results(void){for(unsigned optional=0;optional<2;++optional)for(unsigned status=0;status<256;++status){Model m;model_advertised_write(&m,optional!=0);const uint8_t result[1]={(uint8_t)status};CHECK(complete(&m,result,1)==BTH_OK);if(status){CHECK(m.state.done&&!m.state.available&&!m.state.rx_paced&&!m.state.controller_flow&&!m.state.requires_reset);no_followup(&m);}else{CHECK(!m.state.done&&!m.state.pending);intent(&m,0x0c2e);const uint8_t enabled[2]={0,1};CHECK(complete(&m,enabled,2)==BTH_OK);CHECK(m.state.done&&m.state.available&&m.state.controller_flow&&!m.state.rx_paced);}++cases;}}
static void legitimate_status_forms(void){for(unsigned optional=0;optional<2;++optional)for(unsigned status=1;status<256;++status){Model m;model_advertised_write(&m,optional!=0);CHECK(command_status(&m,(uint8_t)status,4,true)==BTH_OK);CHECK(m.state.done&&!m.state.available&&!m.state.rx_paced&&!m.state.requires_reset);no_followup(&m);++cases;}
 Model accepted;model_advertised_write(&accepted,false);const uint32_t deadline=accepted.state.deadline;CHECK(command_status(&accepted,0,4,true)==BTH_IGNORED&&accepted.state.pending&&!accepted.state.done&&accepted.state.deadline==deadline);CHECK(command_status(&accepted,0,4,true)==BTH_IGNORED&&accepted.state.deadline==deadline);bth_sco_setup_command_t unused;CHECK(bth_sco_setup_next(&accepted.state,accepted.now,&unused)==BTH_MORE);CHECK(bth_sco_setup_expire(&accepted.state,deadline)==BTH_OK&&accepted.state.requires_reset&&accepted.state.reason==BTH_SCO_SETUP_TIMEOUT);no_followup(&accepted);
 for(unsigned status=0;status<256;++status){Model m;model_advertised_write(&m,true);CHECK(command_status(&m,(uint8_t)status,5,true)==BTH_OK);invalid_result(&m,true);++cases;}
 Model foreign;model_advertised_write(&foreign,false);CHECK(command_status(&foreign,1,5,false)==BTH_IGNORED&&foreign.state.pending&&!foreign.state.done);Model short_form;model_advertised_write(&short_form,false);CHECK(command_status(&short_form,1,3,true)==BTH_IGNORED&&short_form.state.pending&&!short_form.state.done);CHECK(bth_sco_setup_expire(&short_form.state,short_form.state.deadline)==BTH_OK&&short_form.state.requires_reset);no_followup(&short_form);
}
static void read_result_shapes(void){for(unsigned stage=0;stage<2;++stage)for(unsigned status=1;status<256;++status)for(unsigned length=1;length<=3;++length){Model m;if(stage)model_verify(&m,true);else model_flow_read(&m,true,true);uint8_t values[3]={(uint8_t)status,0,0};CHECK(complete(&m,values,length)==BTH_OK);if(length==3)invalid_result(&m,stage!=0);else if(stage){CHECK(m.state.done&&!m.state.available&&!m.state.rx_paced&&m.state.reason==BTH_SCO_SETUP_FLOW_UNAVAILABLE);no_followup(&m);}else{CHECK(m.state.done&&!m.state.available&&!m.state.rx_paced&&!m.state.controller_flow&&m.state.reason==BTH_SCO_SETUP_FLOW_UNAVAILABLE);no_followup(&m);}++cases;}
 Model invalid_value;model_verify(&invalid_value,true);const uint8_t invalid[2]={0,2};CHECK(complete(&invalid_value,invalid,sizeof invalid)==BTH_OK);invalid_result(&invalid_value,true);
}
static void capability_and_defaults(void){Model m;model_flow_read(&m,false,false);const uint8_t off[2]={0,0};CHECK(complete(&m,off,2)==BTH_OK);CHECK(m.state.done&&!m.state.available&&!m.state.rx_paced&&!m.state.flow_write_supported&&!m.state.requires_reset&&m.state.reason==BTH_SCO_SETUP_FLOW_UNAVAILABLE);no_followup(&m);const bth_sco_setup_config_t c=configuration(false);CHECK(!c.allow_rx_pacing&&!c.allow_route_configuration);
 Model invalid_discovery;initialize(&invalid_discovery,true);intent(&invalid_discovery,0x1002);const uint8_t bad[2]={1,0};CHECK(complete(&invalid_discovery,bad,2)==BTH_OK);invalid_result(&invalid_discovery,false);
 Model timing;model_start=0xfffff000u;model_advertised_write(&timing,false);const uint32_t deadline=timing.state.deadline;CHECK(bth_sco_setup_expire(&timing.state,deadline-1)==BTH_MORE);CHECK(bth_sco_setup_expire(&timing.state,deadline)==BTH_OK&&timing.state.requires_reset);no_followup(&timing);model_start=100;
}
int main(void){malformed_write_results();valid_write_results();legitimate_status_forms();read_result_shapes();capability_and_defaults();printf("OWN_SCO_PARSER_VALIDATION_PASS cases=%u checks=%u direct_units_only=1 transport_calls=0 firmware_assets=0 device_actions=0\n",cases,checks);return 0;}
